mapper.select:
SELECT a.id, b.id as propertyId, b.serial_number, b.`name`, b.area_id, b.device_number, b.type_name FROM `property_bim_config` a INNER JOIN property_detailed b ON a.business_id = b.id
a.scene_type = #{param.sceneType}
and b.type_id = #{param.typeId}
and b.area_id like CONCAT('%',#{param.areaId},'%')
and (b.`name` like CONCAT('%',#{param.keyword},'%') or b.`serial_number` like CONCAT('%',#{param.keyword},'%'))
order by b.create_time desc
